"use client"

import React, {
    useMemo,
} from "react"
import { Chip, ScrollShadow } from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import dayjs from "dayjs"
import {
    BarChart,
    Bar,
    CartesianGrid,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
} from "recharts"
import { useQueryMyCreditUsageHistoryInfiniteSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCreditUsageHistoryInfiniteSwr"
import { AiCeilSurface } from "@/modules/api/graphql/mutations/types/set-ai-ceil"
import type { QueryMyCreditUsageHistoryItem } from "@/modules/api/graphql/queries/types/my-credit-usage-history"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { InfiniteScrollSentinel } from "@/components/blocks/async/InfiniteScrollSentinel"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"

/** Days shown in the per-day spend chart (matches the chart title copy). */
const CHART_DAYS = 14

/** Display label per provider key; null = the free Auto lane. */
const PROVIDER_LABELS: Record<string, string> = {
    openai: "OpenAI",
    gemini: "Gemini",
}

/**
 * Human label for what a charge row was for. `surface` distinguishes an
 * interview-grading / chatbot charge from a challenge-grading one — rows
 * predating the `surface` column (or from a surface not yet passing it
 * through) fall back to the "Grade challenge" label.
 */
const purposeLabel = (
    item: QueryMyCreditUsageHistoryItem,
    t: ReturnType<typeof useTranslations>,
): string => {
    switch (item.surface) {
    case AiCeilSurface.Interview:
        return t("aiQuota.history.purposeInterview")
    case AiCeilSurface.Chatbot:
        return t("aiQuota.history.purposeChatbot")
    default:
        return t("aiQuota.history.purposeGrade")
    }
}

/** Props for {@link AiUsageHistory}. */
export type AiUsageHistoryProps = Record<string, never>
/**
 * AI usage insight for the `/profile/ai-usage` page: a per-day spend chart, a
 * "by provider" {@link SegmentBar} breakdown, and the charge history as an
 * infinite-scroll list. Self-contained: drives its own `useSWRInfinite` over
 * `myCreditUsageHistory` (offset paginated). Chart/breakdown are computed
 * client-side from the loaded rows.
 *
 * NOTE: linking a charge back to its challenge needs the backend to expose
 * `attemptId` on the history item — not surfaced yet, so rows are read-only.
 *
 * @param props - optional className (placement only).
 */
export const AiUsageHistory = () => {
    const t = useTranslations()

    const {
        data,
        isLoading,
        isValidating,
        error,
        size,
        setSize,
        mutate,
    } = useQueryMyCreditUsageHistoryInfiniteSwr()

    const pages = useMemo(() => data ?? [], [data])
    const items = useMemo(() => pages.flatMap((page) => page.items), [pages])
    const total = pages[0]?.total ?? 0
    const hasMore = items.length < total
    const isLoadingMore = isValidating && size > 0

    // per-day spend buckets (last CHART_DAYS days), from all loaded rows
    const chartData = useMemo(() => {
        const today = dayjs().startOf("day")
        const buckets = new Map<string, number>()
        for (let offset = CHART_DAYS - 1; offset >= 0; offset--) {
            buckets.set(today.subtract(offset, "day").format("DD/MM"), 0)
        }
        for (const item of items) {
            const key = dayjs(item.createdAt).startOf("day").format("DD/MM")
            if (buckets.has(key)) {
                buckets.set(key, (buckets.get(key) ?? 0) + item.credits)
            }
        }
        return [...buckets.entries()].map(([day, credits]) => ({ day, credits }))
    }, [items])

    // credits spent per provider (null provider = free Auto lane)
    const providerSegments = useMemo(() => {
        const byProvider = new Map<string, number>()
        for (const item of items) {
            const key = item.provider ?? "free"
            byProvider.set(key, (byProvider.get(key) ?? 0) + item.credits)
        }
        return [...byProvider.entries()]
            .filter(([, credits]) => credits > 0)
            .sort((a, b) => b[1] - a[1])
            .map(([key, credits]) => ({
                key,
                label: key === "free" ? t("aiQuota.freeTier") : PROVIDER_LABELS[key] ?? key,
                value: credits,
            }))
    }, [items, t])

    const historyItems: Array<SurfaceCardListItem> = items.map((item) => ({
        key: item.id,
        title: item.model ?? t("aiQuota.history.autoModel"),
        subtitle: `${purposeLabel(item, t)} · ${dayjs(item.createdAt).format("HH:mm DD/MM")}`,
        trailing: () => (
            <Chip
                size="sm"
                variant="soft"
                color={item.credits > 0 ? "warning" : "success"}
            >
                <Chip.Label>
                    {`${item.credits} ${t("aiQuota.history.creditsUnit")}`}
                </Chip.Label>
            </Chip>
        ),
    }))

    return (
        <AsyncContent
            isLoading={isLoading && items.length === 0}
            skeleton={(
                <StackV
                    gap={6}
                    items={[
                        () => (
                            <LabeledCard label={t("aiQuota.history.chartTitle")}>
                                <Skeleton className="h-44 w-full rounded-xl" />
                            </LabeledCard>
                        ),
                        () => (
                            <LabeledCard label={t("aiQuota.history.breakdownTitle")}>
                                <Skeleton.SegmentBar legendItems={3} />
                            </LabeledCard>
                        ),
                        () => (
                            <LabeledCard label={t("aiQuota.history.title")}>
                                <StackV
                                    gap={3}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[0, 1, 2, 3].map((row) => () => (
                                        <Skeleton key={row} className="h-12 w-full rounded-xl" />
                                    ))}
                                />
                            </LabeledCard>
                        ),
                    ]}
                />
            )}
            isEmpty={items.length === 0}
            emptyContent={{ title: t("aiQuota.history.empty") }}
            error={error}
            errorContent={{
                title: t("aiQuota.history.title"),
                onRetry: () => { void mutate() },
                retryLabel: t("dashboard.retry"),
            }}
        >
            <div className={""}>
                <StackV
                    gap={6}
                    items={[
                        () => (
                            <LabeledCard label={t("aiQuota.history.chartTitle")}>
                                <div className="h-44 w-full text-accent-soft-foreground">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <BarChart data={chartData} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                            <CartesianGrid
                                                strokeDasharray="3 3"
                                                stroke="currentColor"
                                                className="text-divider"
                                                vertical={false}
                                            />
                                            <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={1} tickLine={false} axisLine={false} />
                                            <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                            <Tooltip
                                                cursor={{ fill: "currentColor", opacity: 0.08 }}
                                                formatter={(value) => [`${value} ${t("aiQuota.history.creditsUnit")}`, ""]}
                                            />
                                            <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                        </BarChart>
                                    </ResponsiveContainer>
                                </div>
                            </LabeledCard>
                        ),
                        ...(providerSegments.length > 0
                            ? [() => (
                                <LabeledCard label={t("aiQuota.history.breakdownTitle")}>
                                    <SegmentBar
                                        ariaLabel={t("aiQuota.history.breakdownTitle")}
                                        segments={providerSegments}
                                    />
                                </LabeledCard>
                            )]
                            : []),
                        () => (
                            <ScrollShadow className="max-h-96">
                                <SurfaceCardList
                                    label={t("aiQuota.history.title")}
                                    items={historyItems}
                                />
                                <InfiniteScrollSentinel
                                    onReach={() => setSize((current) => current + 1)}
                                    disabled={!hasMore || isLoadingMore}
                                />
                            </ScrollShadow>
                        ),
                    ]}
                />
            </div>
        </AsyncContent>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Button,
    Chip,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    AiQuotaLane,
} from "@/components/blocks/ai/AiQuotaLane"
import {
    AiUsageHistory,
} from "./AiUsageHistory"
import { useQueryMyAiQuotaSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiQuotaSwr"
import { pathConfig } from "@/resources/path"
import { AiSubTier } from "@/modules/api/graphql/queries/query-my-ai-settings"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { StackH, StackV } from "@/components/frames/Stack"
import { QuotaLaneVariant } from "@/hooks/quota-lane-variant"
import { useQuotaLaneData } from "@/hooks/useQuotaLaneData"

/**
 * Full AI quota / usage page — Auto + Premium lanes and usage history.
 * Mounted by `/[locale]/profile/ai-usage`.
 */
export const AiUsagePage = () => {
    const t = useTranslations()
    const router = useRouter()
    const locale = useLocale()
    const { data: quota } = useQueryMyAiQuotaSwr()
    const { data: premiumLane, isLoading: isPremiumLaneLoading } = useQuotaLaneData(QuotaLaneVariant.Premium)


    const subscriptionHref = useMemo(
        () => `${pathConfig().locale(locale).profile().build()}/ai-subscription`,
        [
            locale,
        ],
    )

    const onSubscribe = useCallback(() => {
        router.push(subscriptionHref)
    }, [
        router,
        subscriptionHref,
    ])

    // upsell prompt under the credit card: free → "buy a plan"; paid-but-not-max →
    // "upgrade"; on the MAX plan there is nothing left to sell, so it hides.
    const tier = quota?.tier ?? null
    const showUpsell = tier !== AiSubTier.Max
    const upsellText = tier
        ? t("aiQuota.upgradeWarning", { tier: tier.toUpperCase() })
        : t("aiQuota.subscriptionNone")
    const upsellCta = tier ? t("aiQuota.upgradeCta") : t("aiQuota.subscribeCta")

    const bodyItems = [
        () => (
            <SurfaceCard
                label={t("aiQuota.creditPool")}
                action={() => (
                    <Chip
                        size="sm"
                        variant="soft"
                        color={quota?.tier === "max" ? "warning" : "default"}
                    >
                        <Chip.Label>
                            {quota?.tier
                                ? quota.tier.toUpperCase()
                                : t("aiQuota.freeTier")}
                        </Chip.Label>
                    </Chip>
                )}
                body={() => (
                    <AiQuotaLane data={premiumLane} isLoading={isPremiumLaneLoading} />
                )}
            />
        ),
        ...(showUpsell
            ? [() => (
                <StackH
                    gap={4}
                    justify="between"
                    align="center"
                    at="sm"
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => (
                            <Typography type="body-sm" className="text-warning-soft-foreground">
                                {upsellText}
                            </Typography>
                        ),
                        () => (
                            <Button
                                variant="primary"
                                onPress={onSubscribe}
                                className="@app-sm:shrink-0"
                            >
                                {upsellCta}
                            </Button>
                        ),
                    ]}
                />
            )]
            : []),
        () => <AiUsageHistory />,
    ]

    return (
        <div className="flex flex-col gap-10">
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("aiQuota.fullPageTitle")} />}
                title={t("aiQuota.fullPageTitle")}
                description={t("aiQuota.fullPageDescription")}
            />
            <StackV gap={6} items={bodyItems} />
        </div>
    )
}

"use client"

import React, {
    useState,
} from "react"
import { Button, Card, CardContent, Chip, Typography, Spinner } from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { useQueryMyLearningFeedbacksSwr, MY_LEARNING_FEEDBACKS_LIMIT } from "@/hooks/swr/api/graphql/queries/useQueryMyLearningFeedbacksSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link MyFeedbackPage}. */
export type MyFeedbackPageProps = Record<string, never>
/** Map a feedback source to a HeroUI Chip color. */
const SOURCE_COLOR_MAP: Record<string, "accent" | "warning" | "success"> = {
    challenge: "accent",
    task: "warning",
    cv: "success",
}

/**
 * The learner's received feedback as a list — source chip, title, related course
 * and summary. "Load more" grows the page window via a single offset=0 query
 * (`myLearningFeedbacks`).
 *
 * @param props - optional root className.
 */
export const MyFeedbackPage = () => {
    const t = useTranslations()
    const locale = useLocale()

    /** How many pages have been requested (drives the growing window). */
    const [pageCount, setPageCount] = useState(1)

    const swr = useQueryMyLearningFeedbacksSwr(
        0,
        MY_LEARNING_FEEDBACKS_LIMIT * pageCount,
    )
    const items = swr.data?.items ?? []
    const total = swr.data?.total ?? 0
    const hasMore = items.length < total

    const formatDate = (iso: string): string =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    const skeletonItems = [0, 1, 2].map((row) => () => (
        <Card key={row}>
            <CardContent>
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => (
                            <StackH
                                gap={4}
                                align="center"
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => <Skeleton.Chip />,
                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                ]}
                            />
                        ),
                        () => <Skeleton.Typography type="body-sm" width="3/4" />,
                    ]}
                />
            </CardContent>
        </Card>
    ))

    const feedbackItems = [
        ...items.map((item) => () => (
            <Card key={item.id}>
                <CardContent>
                    <StackV
                        gap={3}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <Cluster
                                    gap={4}
                                    align="center"
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => (
                                            <Chip
                                                size="sm"
                                                variant="soft"
                                                color={SOURCE_COLOR_MAP[item.source] ?? "accent"}
                                            >
                                                <Chip.Label>
                                                    {t(`profileSettings.learning.feedback.source.${item.source}`)}
                                                </Chip.Label>
                                            </Chip>
                                        ),
                                        () => (
                                            <Typography type="body-sm" weight="medium">
                                                {item.title}
                                            </Typography>
                                        ),
                                        () => (
                                            <Box principle="push-end" className="ml-auto"
                                                explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                                <Typography type="body-xs" color="muted">
                                                    {formatDate(item.createdAt)}
                                                </Typography>
                                            </Box>
                                        ),
                                    ]}
                                />
                            ),
                            ...(item.courseTitle
                                ? [() => (
                                    <Typography type="body-xs" color="muted">
                                        {item.courseTitle}
                                    </Typography>
                                )]
                                : []),
                            () => (
                                <Typography type="body-sm" color="muted">
                                    {item.summary}
                                </Typography>
                            ),
                        ]}
                    />
                </CardContent>
            </Card>
        )),
        ...(hasMore
            ? [() => (
                <div className="flex justify-center">
                    <Button
                        variant="ghost"
                        size="sm"
                        isDisabled={swr.isValidating}
                        onPress={() => setPageCount((count) => count + 1)}
                    >
                        {swr.isValidating ? (
                            <Spinner color="current" size="sm" />
                        ) : null}
                        {t("profileSettings.learning.loadMore")}
                    </Button>
                </div>
            )]
            : []),
    ]

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileSettings.learning.feedback.title")} />}
                title={t("profileSettings.learning.feedback.title")}
                description={t("profileSettings.learning.feedback.subtitle")}
            />

            <SurfaceCard
                label={t("profileSettings.learning.feedback.title")}

                body={() => (
                    <AsyncContent
                        isLoading={!swr.data && !swr.error}
                        skeleton={<StackV gap={4} items={skeletonItems} />}
                        isEmpty={items.length === 0}
                        emptyContent={{
                            title: t("profileSettings.learning.feedback.empty"),
                        }}
                        error={!swr.data ? swr.error : undefined}
                        errorContent={{
                            title: t("profileSettings.learning.feedback.empty"),
                            onRetry: () => { void swr.mutate() },
                            retryLabel: t("profileSettings.learning.loadMore"),
                        }}
                    >
                        <StackV gap={4} items={feedbackItems} />
                    </AsyncContent>
                )}
            />
        </div>
    )
}

