import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { MascotBadge } from "@/components/blocks/profile/MascotBadge"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import { getRank } from "@/modules/utils/rank"

/** One labelled achievement bucket: a group key plus the badge slugs it holds. */
interface AchievementGroup {
    /** i18n key identifying the group (e.g. `learning`, `skills`). */
    key: string
    /** Badge slugs displayed under this group, in order. */
    slugs: ReadonlyArray<string>
}

/**
 * Achievement wall layout: each badge slug bucketed into a labelled group, in
 * display order. Slugs not listed here fall into a trailing "other" group, so
 * adding a badge never silently drops it.
 */
const ACHIEVEMENT_GROUPS: ReadonlyArray<AchievementGroup> = [
    {
        key: "learning",
        slugs: [
            "baby-duckling",
            "blazing-fox",
            "crowned-owl",
            "polyglot-parrot",
        ],
    },
    {
        key: "skills",
        slugs: [
            "sword-shark",
            "bug-hunting-chameleon",
            "brainy-octopus",
        ],
    },
    {
        key: "community",
        slugs: [
            "guiding-elephant",
            "busy-bee",
            "champion-lion",
        ],
    },
    {
        key: "course",
        slugs: [
            "architect-rhino",
            "fullstack-monkey",
            "devops-wolf",
        ],
    },
]

/** Props for {@link ProfileAchievements}. */
export type ProfileAchievementsProps = WithClassNames<undefined>

/**
 * Achievements tab of the public profile — the profile owner's badge wall. Earned
 * badges show in full colour; locked ones are dimmed with progress toward the
 * threshold. Self-contained container: reads the target user id from the route
 * and drives its own SWR. Mirrors the dashboard achievements grid but for any
 * user (not just the viewer). Badge art comes from MinIO (`iconKey`), falling
 * back to a medal placeholder.
 *
 * @param props - optional className for the root element.
 */
export const ProfileAchievements = () => {
    const t = useTranslations()
    // route carries the username; resolve it to the entity id the achievements
    // query keys off (the profile fetch is SWR-deduped with the parent + tabs)
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserAchievementsSwr(userId)

    const items = data ?? []

    const renderItem = (item: (typeof items)[number]) => {
        // earned → rank (coloured by its ring) · rarity %; locked → progress
        const { labelKey, ring } = getRank(item.earned, item.tierReached)
        const rankLabel = labelKey ? t(labelKey) : null
        // shared meta line: rank in its ring colour + rarity muted, or locked progress
        const meta = item.earned && rankLabel ? (
            <StackH gap={3} items={[
                () => (
                    <Typography type="body-xs" weight="medium" style={{ color: ring }}>
                        {rankLabel}
                    </Typography>
                ),
                ...(item.rarityPercent != null
                    ? [() => (
                        <Typography type="body-xs" color="muted">
                            · {item.rarityPercent}%
                        </Typography>
                    )]
                    : []),
            ]} />
        ) : (
            <Typography type="body-xs" color="muted">
                {item.currentValue}/{item.threshold}
            </Typography>
        )
        return (
            <Tooltip
                key={item.slug}
                delay={200}
            >
                <Tooltip.Trigger>
                    <div className="max-w-32 min-w-0 cursor-default text-center">
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            align="center" items={[
                                () => (
                                    <MascotBadge
                                        objectKey={item.iconKey}
                                        name={item.name}
                                        earned={item.earned}
                                        tierReached={item.tierReached}
                                        size={48}
                                    />
                                ),
                                () => (
                                    <Typography type="body-xs" truncate className="w-full">
                                        {item.name}
                                    </Typography>
                                ),
                                () => meta,
                            ]} />
                    </div>
                </Tooltip.Trigger>
                <Tooltip.Content
                    placement="top"
                    showArrow
                    className="max-w-[240px]"
                >
                    <Tooltip.Arrow />
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        align="center" items={[
                            () => (
                                <MascotBadge
                                    objectKey={item.iconKey}
                                    name={item.name}
                                    earned={item.earned}
                                    tierReached={item.tierReached}
                                    size={56}
                                />
                            ),
                            () => (
                                <Typography type="body-sm" weight="semibold">
                                    {item.name}
                                </Typography>
                            ),
                            () => (
                                <Typography type="body-xs" color="muted">
                                    {item.description}
                                </Typography>
                            ),
                            () => meta,
                        ]} />
                </Tooltip.Content>
            </Tooltip>
        )
    }

    // earned badges first (then higher tier, then closer-to-earning) so the flex
    // leads and locked/grey badges sink to the back of each group
    const byFlex = (
        a: (typeof items)[number],
        b: (typeof items)[number],
    ): number => {
        if (a.earned !== b.earned) {
            return a.earned ? -1 : 1
        }
        const aTier = a.tierReached ?? 0
        const bTier = b.tierReached ?? 0
        if (aTier !== bTier) {
            return bTier - aTier
        }
        // both locked → the one nearer its threshold ranks first
        const aProgress = a.threshold > 0 ? a.currentValue / a.threshold : 0
        const bProgress = b.threshold > 0 ? b.currentValue / b.threshold : 0
        return bProgress - aProgress
    }

    // bucket the wall into labelled groups (display order), with a trailing
    // "other" group catching any slug not assigned above
    const assigned = new Set(ACHIEVEMENT_GROUPS.flatMap((group) => group.slugs))
    const groups = ACHIEVEMENT_GROUPS
        .map((group) => ({
            key: group.key,
            items: items.filter((item) => group.slugs.includes(item.slug)).sort(byFlex),
        }))
        .filter((group) => group.items.length > 0)
    const other = items.filter((item) => !assigned.has(item.slug)).sort(byFlex)
    if (other.length > 0) {
        groups.push({
            key: "other",
            items: other,
        })
    }

    return (
        <LabeledCard

            label={t("publicProfile.tabs.achievements")}
        >
            <AsyncContent
                isLoading={(isLoading || !userId) && items.length === 0}
                skeleton={
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={
                            [0, 1].map(() => () => (
                                <StackV gap={4} items={[
                                    () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                    () => (
                                        <Cluster gap={5} principle="group-boundary"
                                            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                            items={
                                                [0, 1, 2, 3].map(() => () => (
                                                    <div className="w-24 text-center">
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                            align="center" items={[
                                                                () => <Skeleton className="size-12 rounded-full" />,
                                                                () => <Skeleton.Typography type="body-xs" width="3/4" />,
                                                                () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                            ]} />
                                                    </div>
                                                ))
                                            } />
                                    ),
                                ]} />
                            ))
                        } />
                }
                isEmpty={items.length === 0}
                emptyContent={{
                    title: t("publicProfile.achievementsEmpty"),
                }}
                error={error}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => mutate(),
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <StackV gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={
                        groups.map((group) => () => (
                            <StackV gap={4} items={[
                                () => (
                                    <Label>
                                        {t(`publicProfile.achievementGroups.${group.key}`)}
                                    </Label>
                                ),
                                () => (
                                    <Cluster gap={5} principle="group-boundary"
                                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                        items={
                                            group.items.map((item) => () => renderItem(item))
                                        } />
                                ),
                            ]} />
                        ))
                    } />
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Button,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { queryResolveRoute } from "@/modules/api/graphql/queries/query-resolve-route"
import type { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import { useQueryUserFeedSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserFeedSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useMutateReactActivitySwr } from "@/hooks/swr/api/graphql/mutations/useMutateReactActivitySwr"
import { useAppSelector } from "@/redux/hooks"
import { ActivityFeed } from "@/components/blocks/feed/ActivityFeed"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { StackH, StackV } from "@/components/frames/Stack"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** Props for {@link ProfileActivity}. */
export type ProfileActivityProps = WithClassNames<undefined>

/**
 * Activity-tab section — the profile owner's timeline, rendered by the shared
 * {@link ActivityFeed} block (avatar + activity-type badge · actor·action·target
 * sentence · relative time, grouped by day, milestone roll-up, never-blank target).
 * This feature owns the fetch (infinite SWR), the "load more" pager, the section
 * card + states, and the route resolver it hands the block. Self-hides when empty.
 *
 * @param props - optional className (placement only).
 */
export const ProfileActivity = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const {
        data,
        size,
        setSize,
        isLoading,
        isValidating,
        error,
        mutate,
    } = useQueryUserFeedSwr(userId)
    const { trigger: reactActivity } = useMutateReactActivitySwr()

    /** React to a timeline activity, then revalidate. Own items are read-only
     * (server sets `isMine` → the feed suppresses the picker), so this only ever
     * fires when viewing someone else's profile. */
    const onReact = useCallback(
        async (activityId: string, type: ReactionType | null) => {
            await reactActivity({ activityId, type })
            await mutate()
        },
        [
            reactActivity,
            mutate,
        ],
    )

    // flatten every loaded page into a single newest-first item list
    const items = useMemo(
        () => (data ?? []).flatMap((page) => page.items),
        [data],
    )
    const hasMore = Boolean(data && data.length > 0 && data[data.length - 1].nextCursor !== null)
    const isLoadingMore = isValidating && Boolean(data) && size > 0

    /** Resolve an entity's route via the index, then navigate (no-op if unroutable). */
    const onResolve = useCallback(
        (globalId: string | null | undefined): (() => void) | undefined => {
            if (!globalId) {
                return undefined
            }
            return () => {
                void (async () => {
                    const response = await queryResolveRoute({ request: { globalId } })
                    const path = response.data?.resolveRoute?.data?.path
                    if (path) {
                        router.push(`/${locale}${path}`)
                    }
                })()
            }
        },
        [
            locale,
            router,
        ],
    )

    return (
        <LabeledCard

            label={t("publicProfile.recentActivity")}
        >
            <AsyncContent
                isLoading={(isLoading || !userId) && items.length === 0}
                skeleton={(
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={
                            [0, 1].map(() => () => (
                                <StackV gap={4} items={[
                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                    () => (
                                        <SurfaceListCard bordered>
                                            {[0, 1, 2].map((row) => (
                                                <SurfaceListCardItem key={row}>
                                                    <StackH gap={3} principle="identity"
                                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                        align="start" items={[
                                                            () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                                            () => (
                                                                <StackV gap={1} classNames={["flex-1"]} items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                                                ]} />
                                                            ),
                                                        ]} />
                                                </SurfaceListCardItem>
                                            ))}
                                        </SurfaceListCard>
                                    ),
                                ]} />
                            ))
                        } />
                )}
                isEmpty={items.length === 0}
                emptyContent={{
                    title: t("publicProfile.activityEmpty"),
                    description: t("publicProfile.activityEmptyHint"),
                }}
                error={items.length === 0 ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => {
                        void mutate()
                    },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <StackV gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <ActivityFeed
                                items={items}
                                onResolve={onResolve}
                                onReact={authenticated ? onReact : undefined}
                                bordered
                            />
                        ),
                        ...(hasMore
                            ? [() => (
                                <div className="flex justify-center">
                                    <Button
                                        variant="secondary"
                                        size="sm"
                                        isPending={isLoadingMore}
                                        onPress={() => setSize(size + 1)}
                                    >
                                        {t("publicProfile.loadMore")}
                                    </Button>
                                </div>
                            )]
                            : []),
                    ]} />
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React from "react"
import {
    ProfileAchievements,
} from "./ProfileAchievements"
import {
    ProfileActivity,
} from "./ProfileActivity"
import {
    ProfileSectionGuard,
} from "@/components/blocks/profile/ProfileSectionGuard"

/** Props for {@link ProfileActivityPage}. */
export type ProfileActivityPageProps = Record<string, never>
/**
 * "Activity" tab of the public profile (NEW-PROFILE.spec.md §7.4). A single
 * centered column with two editorial sections — earned achievements (badge wall
 * by tier/rank) then the activity timeline. Courses live in the Overview tab, so
 * they are not repeated here. A thin composition: each section is its own
 * self-fetching `LabeledCard` that self-hides when empty, so this wrapper only
 * stacks them with the `gap-6` vertical rhythm.
 *
 * @param props - {@link ProfileActivityPageProps}
 */
export const ProfileActivityPage = () => {
    return (
        <ProfileSectionGuard section="activity">
            <div className={"flex flex-col gap-6"}>
                <ProfileAchievements />
                <ProfileActivity />
            </div>
        </ProfileSectionGuard>
    )
}

"use client"

import React from "react"
import { FileTextIcon, PencilSimpleIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryPublicUserCvSwr } from "@/hooks/swr/api/graphql/queries/useQueryPublicUserCvSwr"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"

/**
 * A4 "paper" frame reused from the CV editor's live preview
 * (`CvBlocksWorkspace/CvPdfPreview`) — a scrollable, white, A4-proportioned card.
 * A page-proportioned sheet is not a shape any frame names, so it stays a literal
 * on `Box` — but ONE literal, shared by the resting and loaded states.
 */
const PAPER_FRAME =
    "relative mx-auto flex h-full max-w-[820px] flex-col overflow-hidden rounded-3xl bg-white shadow-surface"

/** Viewport-proportioned height of the resting sheet. */
const RESTING_HEIGHT = "h-[70vh] min-h-[480px]"

/** Viewport-proportioned height of the loaded sheet. */
const LOADED_HEIGHT = "h-[80vh] min-h-[520px]"

const PublicCvEditButton = ({ label, onPress }: PublicCvEditButtonProps) => (
    <Button
        label={label}
        variant="secondary"
        prefixIcon={PencilSimpleIcon}
        onPress={onPress}
    />
)

/**
 * Public CV tab (`/profile/<username>/cv`) — the read-only, PDF-only view of the
 * ONE CV a user has flagged public. Anyone (signed in or not) can view it. When
 * the viewer IS the owner (`isSelf`), an "Edit CV" button links to the private
 * editor gallery (`/profile/cv`). Branches:
 *
 *   - data + `pdfUrl`   → the compiled PDF embedded read-only in the paper frame
 *   - data, no `pdfUrl` → the public CV was never compiled (a note)
 *   - no data           → the user has no public CV
 *
 * Self-contained: reads the username from the route, derives `isSelf` from the
 * viewer (redux) + the profile owner (`userProfile`), and drives its own SWR.
 */
export const ProfilePublicCvPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const viewer = useAppSelector((state) => state.user.user)
    const { data: user } = useQueryUserProfileSwr(username)
    const isSelf = !!viewer && !!user?.id && viewer.id === user.id

    const cvSwr = useQueryPublicUserCvSwr(username)
    const cv = cvSwr.data
    const isSkeleton = cvSwr.isLoading && !cvSwr.data

    const editLabel = t("publicProfile.publicCv.editCta")
    const onEdit = () => router.push(pathConfig().locale(locale).profile().cv().build())

    // error beats a stale loading flag (BLOCK-8 order).
    if (cvSwr.error) {
        return (
            <AsyncContentError
                title={t("publicProfile.publicCv.errorTitle")}
                onRetry={() => cvSwr.mutate()}
                retryLabel={t("publicProfile.publicCv.retry")}
            />
        )
    }

    // the resting state IS the paper frame, shimmering — same literal, same proportions
    if (isSkeleton) {
        return (
            <Box className={RESTING_HEIGHT}>
                <Box principle="center-measure" className={PAPER_FRAME}
                    explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
                >
                    <Skeleton className="h-full w-full" />
                </Box>
            </Box>
        )
    }

    // no public CV at all, or flagged public but never compiled — same shape, different line
    if (!cv || !cv.pdfUrl) {
        return (
            <AsyncContentEmpty
                icon={FileTextIcon}
                title={cv
                    ? t("publicProfile.publicCv.notCompiled")
                    : t("publicProfile.publicCv.emptyTitle")}
                description={isSelf
                    ? (cv
                        ? t("publicProfile.publicCv.notCompiledSelfHint")
                        : t("publicProfile.publicCv.emptySelfHint"))
                    : undefined}
                action={isSelf ? () => <PublicCvEditButton label={editLabel} onPress={onEdit} /> : undefined}
            />
        )
    }

    // captured out of the guard: property narrowing does not survive into the slot closures
    const pdfUrl = cv.pdfUrl
    const pdfTitle = cv.label || t("publicProfile.publicCv.iframeTitle")

    return (
        <StackV
            identity={{ tier: "block", component: "ProfilePublicCvPage" }}
            gap={5}
            principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                ...(isSelf ? [() => (
                    <div className="flex justify-end">
                        <PublicCvEditButton label={editLabel} onPress={onEdit} />
                    </div>
                )] : []),
                () => (
                    <Box className={LOADED_HEIGHT}>
                        <Box principle="center-measure" className={PAPER_FRAME}
                            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
                        >
                            <iframe
                                title={pdfTitle}
                                src={pdfUrl}
                                className="h-full w-full flex-1 border-0"
                            />
                        </Box>
                    </Box>
                ),
            ]}
        />
    )
}

type PublicCvEditButtonProps = { label: string; onPress: () => void }
